describe('Context Menu on Table Row', () => {
    beforeEach(() => {
        cy.visit('/table-list'); // Adjust the URL to your application
    });

    it('should display context menu on right-clicking a row', () => {
        cy.get('table tbody tr').first().rightclick(); // Right-click on the first row
        cy.get('.context-menu').should('be.visible'); // Check if context menu is visible
        cy.get('.context-menu').contains('Edit').should('exist'); // Check for 'Edit' option
        cy.get('.context-menu').contains('Delete').should('exist'); // Check for 'Delete' option
    });

    it('should not display context menu when right-clicking outside a row', () => {
        cy.get('body').rightclick(); // Right-click on the body
        cy.get('.context-menu').should('not.exist'); // Ensure context menu does not appear
    });
});
